  "home.svc.webdesign": { en: "Web Design", es: "Diseño Web", zh: "网页设计", yue: "網頁設計", ru: "Веб-дизайн", yi: "וועב דיזיין", bn: "ওয়েব ডিজাইন", ko: "웹 디자인", ht: "Konsepsyon Entènèt", it: "Web Design", ar: "تصميم الويب", pl: "Projektowanie stron" },
  "home.svc.webdesign.d": { en: "Brand-led interfaces designed in-house, pixel by pixel. No themes, no page builders.", es: "Interfaces guiadas por la marca, diseñadas internamente, píxel a píxel. Sin plantillas ni constructores de páginas.", zh: "以品牌为核心、在内部逐像素设计的界面。没有模板，没有页面搭建器。", yue: "以品牌為核心、喺內部逐像素設計嘅介面。冇模板，冇網頁生成器。", ru: "Интерфейсы на основе бренда, спроектированные у нас, пиксель за пикселем. Никаких шаблонов и конструкторов.", yi: "בראַנד-געפֿירטע אינטערפֿייסן דיזיינד אין הויז, פּיקסל בײַ פּיקסל. קיין טעמעס, קיין בוי-מכשירים.", bn: "ব্র্যান্ড-নির্ভর ইন্টারফেস, নিজেদের হাতে পিক্সেল ধরে ডিজাইন করা। কোনো থিম নেই, পেজ বিল্ডার নেই।", ko: "브랜드 중심 인터페이스를 사내에서 픽셀 단위로 디자인합니다. 테마도, 페이지 빌더도 없습니다.", ht: "Entèfas ki gide pa mak, konsevwa anndan, piksèl pa piksèl. Pa gen tèm, pa gen konstriktè paj.", it: "Interfacce guidate dal brand, progettate internamente, pixel per pixel. Niente temi, niente page builder.", ar: "واجهات مبنية على الهوية، مصممة داخليًا بكسلًا بكسل. بلا قوالب ولا أدوات بناء صفحات.", pl: "Interfejsy oparte na marce, projektowane u nas, piksel po pikselu. Bez szablonów i kreatorów stron." },
  "home.svc.dev.d": { en: "Hand-written React. Fast, accessible, and built to outlast the next redesign.", es: "React escrito a mano. Rápido, accesible y construido para durar más que el próximo rediseño.", zh: "手写的 React。快速、无障碍，并且经得起下一次改版。", yue: "人手寫嘅 React。快速、無障礙，仲捱得過下一次改版。", ru: "React, написанный вручную. Быстрый, доступный и созданный пережить следующий редизайн.", yi: "האַנט-געשריבן React. גיך, צוטריטלעך, און געבויט צו איבערלעבן דעם קומעדיקן רעדיזיין.", bn: "হাতে লেখা React। দ্রুত, অ্যাক্সেসযোগ্য এবং পরবর্তী রিডিজাইনকেও টিকিয়ে রাখার মতো।", ko: "손으로 작성한 React. 빠르고 접근성이 뛰어나며 다음 리디자인까지 견디도록 만듭니다.", ht: "React ekri alamen. Rapid, aksesib, epi bati pou dire pi lontan pase pwochen rdizayn nan.", it: "React scritto a mano. Veloce, accessibile e costruito per durare oltre il prossimo restyling.", ar: "React مكتوب يدويًا. سريع وسهل الوصول ومبني ليدوم أطول من إعادة التصميم القادمة.", pl: "Ręcznie pisany React. Szybki, dostępny i stworzony, by przetrwać kolejny redesign." },
  "home.svc.seo": { en: "SEO Foundation", es: "Base de SEO", zh: "SEO 基础", yue: "SEO 基礎", ru: "Фундамент SEO", yi: "SEO יסוד", bn: "এসইও ভিত্তি", ko: "SEO 기반", ht: "Baz SEO", it: "Fondamenta SEO", ar: "أساس السيو", pl: "Fundament SEO" },
  "home.svc.seo.d": { en: "Technical SEO, local search, schema, baked in from the first commit.", es: "SEO técnico, búsqueda local y schema, integrados desde el primer commit.", zh: "技术 SEO、本地搜索、结构化数据，从第一次提交就融入其中。", yue: "技術 SEO、本地搜尋、結構化數據，由第一次提交就整合喺入面。", ru: "Технический SEO, локальный поиск и schema — заложены с первого коммита.", yi: "טעכנישער SEO, לאָקאַלער זוך, schema, אַרייַנגעבאַקן פֿון ערשטן commit.", bn: "টেকনিক্যাল এসইও, লোকাল সার্চ, স্কিমা, প্রথম কমিট থেকেই অন্তর্ভুক্ত।", ko: "기술 SEO, 로컬 검색, 스키마를 첫 커밋부터 반영합니다.", ht: "SEO teknik, rechèch lokal, schema, entegre depi premye commit la.", it: "SEO tecnico, ricerca locale e schema, integrati dal primo commit.", ar: "سيو تقني، بحث محلي، وschema، مدمجة منذ أول commit.", pl: "Techniczne SEO, wyszukiwanie lokalne i schema, wbudowane od pierwszego commita." },
  "home.svc.analytics.d": { en: "We instrument everything, then read the numbers back to you in plain English.", es: "Medimos todo y luego te explicamos las cifras en lenguaje claro.", zh: "我们对一切进行埋点，再用通俗易懂的语言把数字讲给你听。", yue: "我哋為一切加上追蹤，再用淺白嘅語言將數字講返俾你聽。", ru: "Мы отслеживаем всё, а затем объясняем цифры простым языком.", yi: "מיר מעסטן אַלץ, און דערנאָך לייענען די נומערן צוריק צו אײַך אין פּשוטן לשון.", bn: "আমরা সবকিছু পরিমাপ করি, তারপর সংখ্যাগুলো সহজ ভাষায় আপনাকে বুঝিয়ে দিই।", ko: "모든 것을 계측한 뒤, 그 수치를 쉬운 말로 다시 설명해 드립니다.", ht: "Nou mezire tout bagay, epi nou li chif yo ba ou an lang klè.", it: "Misuriamo tutto, poi ti spieghiamo i numeri in parole semplici.", ar: "نقيس كل شيء، ثم نشرح لك الأرقام بلغة بسيطة.", pl: "Mierzymy wszystko, a potem tłumaczymy liczby prostym językiem." },

